        dq = (adcs_quat_t){1.0, 0.5 * w->x * dt, 0.5 * w->y * dt, 0.5 * w->z * dt};
    } else {
        half = 0.5 * theta;
        s = sin(half) / nw;
        dq = (adcs_quat_t){cos(half), s * w->x, s * w->y, s * w->z};
